func schema_sigsk8sio_cluster_api_provider_azure_api_v1beta1_SysctlConfig(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "SysctlConfig specifies the settings for Linux agent nodes.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"fsAioMaxNr": {
						SchemaProps: spec.SchemaProps{
							Description: "FsAioMaxNr specifies the maximum number of system-wide asynchronous io requests. Valid values are 65536-6553500 (inclusive). Maps to fs.aio-max-nr.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"fsFileMax": {
						SchemaProps: spec.SchemaProps{
							Description: "FsFileMax specifies the max number of file-handles that the Linux kernel will allocate, by increasing increases the maximum number of open files permitted. Valid values are 8192-12000500 (inclusive). Maps to fs.file-max.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"fsInotifyMaxUserWatches": {
						SchemaProps: spec.SchemaProps{
							Description: "FsInotifyMaxUserWatches specifies the number of file watches allowed by the system. Each watch is roughly 90 bytes on a 32-bit kernel, and roughly 160 bytes on a 64-bit kernel. Valid values are 781250-2097152 (inclusive). Maps to fs.inotify.max_user_watches.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"fsNrOpen": {
						SchemaProps: spec.SchemaProps{
							Description: "FsNrOpen specifies the maximum number of file-handles a process can allocate. Valid values are 8192-20000500 (inclusive). Maps to fs.nr_open.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"kernelThreadsMax": {
						SchemaProps: spec.SchemaProps{
							Description: "KernelThreadsMax specifies the maximum number of all threads that can be created. Valid values are 20-513785 (inclusive). Maps to kernel.threads-max.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreNetdevMaxBacklog": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreNetdevMaxBacklog specifies maximum number of packets, queued on the INPUT side, when the interface receives packets faster than kernel can process them. Valid values are 1000-3240000 (inclusive). Maps to net.core.netdev_max_backlog.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreOptmemMax": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreOptmemMax specifies the maximum ancillary buffer size (option memory buffer) allowed per socket. Socket option memory is used in a few cases to store extra structures relating to usage of the socket. Valid values are 20480-4194304 (inclusive). Maps to net.core.optmem_max.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreRmemDefault": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreRmemDefault specifies the default receive socket buffer size in bytes. Valid values are 212992-134217728 (inclusive). Maps to net.core.rmem_default.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreRmemMax": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreRmemMax specifies the maximum receive socket buffer size in bytes. Valid values are 212992-134217728 (inclusive). Maps to net.core.rmem_max.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreSomaxconn": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreSomaxconn specifies maximum number of connection requests that can be queued for any given listening socket. An upper limit for the value of the backlog parameter passed to the listen(2)(https://man7.org/linux/man-pages/man2/listen.2.html) function. If the backlog argument is greater than the somaxconn, then it's silently truncated to this limit. Valid values are 4096-3240000 (inclusive). Maps to net.core.somaxconn.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreWmemDefault": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreWmemDefault specifies the default send socket buffer size in bytes. Valid values are 212992-134217728 (inclusive). Maps to net.core.wmem_default.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netCoreWmemMax": {
						SchemaProps: spec.SchemaProps{
							Description: "NetCoreWmemMax specifies the maximum send socket buffer size in bytes. Valid values are 212992-134217728 (inclusive). Maps to net.core.wmem_max.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4IPLocalPortRange": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4IPLocalPortRange is used by TCP and UDP traffic to choose the local port on the agent node. PortRange should be specified in the format \"first last\". First, being an integer, must be between [1024 - 60999]. Last, being an integer, must be between [32768 - 65000]. Maps to net.ipv4.ip_local_port_range.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"netIpv4NeighDefaultGcThresh1": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4NeighDefaultGcThresh1 specifies the minimum number of entries that may be in the ARP cache. Garbage collection won't be triggered if the number of entries is below this setting. Valid values are 128-80000 (inclusive). Maps to net.ipv4.neigh.default.gc_thresh1.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4NeighDefaultGcThresh2": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4NeighDefaultGcThresh2 specifies soft maximum number of entries that may be in the ARP cache. ARP garbage collection will be triggered about 5 seconds after reaching this soft maximum. Valid values are 512-90000 (inclusive). Maps to net.ipv4.neigh.default.gc_thresh2.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4NeighDefaultGcThresh3": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4NeighDefaultGcThresh3 specified hard maximum number of entries in the ARP cache. Valid values are 1024-100000 (inclusive). Maps to net.ipv4.neigh.default.gc_thresh3.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4TCPFinTimeout": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPFinTimeout specifies the length of time an orphaned connection will remain in the FIN_WAIT_2 state before it's aborted at the local end. Valid values are 5-120 (inclusive). Maps to net.ipv4.tcp_fin_timeout.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4TCPKeepaliveProbes": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPKeepaliveProbes specifies the number of keepalive probes TCP sends out, until it decides the connection is broken. Valid values are 1-15 (inclusive). Maps to net.ipv4.tcp_keepalive_probes.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4TCPKeepaliveTime": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPKeepaliveTime specifies the rate at which TCP sends out a keepalive message when keepalive is enabled. Valid values are 30-432000 (inclusive). Maps to net.ipv4.tcp_keepalive_time.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4TCPMaxSynBacklog": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPMaxSynBacklog specifies the maximum number of queued connection requests that have still not received an acknowledgment from the connecting client. If this number is exceeded, the kernel will begin dropping requests. Valid values are 128-3240000 (inclusive). Maps to net.ipv4.tcp_max_syn_backlog.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4TCPMaxTwBuckets": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPMaxTwBuckets specifies maximal number of timewait sockets held by system simultaneously. If this number is exceeded, time-wait socket is immediately destroyed and warning is printed. Valid values are 8000-1440000 (inclusive). Maps to net.ipv4.tcp_max_tw_buckets.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netIpv4TCPTwReuse": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPTwReuse is used to allow to reuse TIME-WAIT sockets for new connections when it's safe from protocol viewpoint. Maps to net.ipv4.tcp_tw_reuse.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"netIpv4TCPkeepaliveIntvl": {
						SchemaProps: spec.SchemaProps{
							Description: "NetIpv4TCPkeepaliveIntvl specifies the frequency of the probes sent out. Multiplied by tcpKeepaliveprobes, it makes up the time to kill a connection that isn't responding, after probes started. Valid values are 1-75 (inclusive). Maps to net.ipv4.tcp_keepalive_intvl.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netNetfilterNfConntrackBuckets": {
						SchemaProps: spec.SchemaProps{
							Description: "NetNetfilterNfConntrackBuckets specifies the size of hash table used by nf_conntrack module to record the established connection record of the TCP protocol. Valid values are 65536-147456 (inclusive). Maps to net.netfilter.nf_conntrack_buckets.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"netNetfilterNfConntrackMax": {
						SchemaProps: spec.SchemaProps{
							Description: "NetNetfilterNfConntrackMax specifies the maximum number of connections supported by the nf_conntrack module or the size of connection tracking table. Valid values are 131072-1048576 (inclusive). Maps to net.netfilter.nf_conntrack_max.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"vmMaxMapCount": {
						SchemaProps: spec.SchemaProps{
							Description: "VMMaxMapCount specifies the maximum number of memory map areas a process may have. Maps to vm.max_map_count. Valid values are 65530-262144 (inclusive).",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"vmSwappiness": {
						SchemaProps: spec.SchemaProps{
							Description: "VMSwappiness specifies aggressiveness of the kernel in swapping memory pages. Higher values will increase aggressiveness, lower values decrease the amount of swap. Valid values are 0-100 (inclusive). Maps to vm.swappiness.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"vmVfsCachePressure": {
						SchemaProps: spec.SchemaProps{
							Description: "VMVfsCachePressure specifies the percentage value that controls tendency of the kernel to reclaim the memory, which is used for caching of directory and inode objects. Valid values are 1-500 (inclusive). Maps to vm.vfs_cache_pressure.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
				},
			},
		},
	}
}

