func schema_sigsk8sio_cluster_api_provider_azure_api_v1beta1_UefiSettings(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "UefiSettings specifies the security settings like secure boot and vTPM used while creating the virtual machine.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"secureBootEnabled": {
						SchemaProps: spec.SchemaProps{
							Description: "SecureBootEnabled specifies whether secure boot should be enabled on the virtual machine. Secure Boot verifies the digital signature of all boot components and halts the boot process if signature verification fails. If omitted, the platform chooses a default, which is subject to change over time, currently that default is false.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"vTpmEnabled": {
						SchemaProps: spec.SchemaProps{
							Description: "VTpmEnabled specifies whether vTPM should be enabled on the virtual machine. When true it enables the virtualized trusted platform module measurements to create a known good boot integrity policy baseline. The integrity policy baseline is used for comparison with measurements from subsequent VM boots to determine if anything has changed. This is required to be set to Enabled if SecurityEncryptionType is defined. If omitted, the platform chooses a default, which is subject to change over time, currently that default is false.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
				},
			},
		},
	}
}

